let sent = []
let archived = []
let last_id = ""
let last_undo = ""
let last_undo_label = ""
let draft = ""
let status = "Ready."
let depth = 0
let sel = "m1"

fn has_item(list, x){ for v in list { if v == x { return true } } false }

fn pick(cond, on, off){ if cond { on } else { off } }

fn msg_of(id){
    for m in msgs { if m.id == id { return m } }
    nil
}

fn inbox(){
    let out = []
    for m in msgs { if !has_item(archived, m.id) { out.push(m) } }
    out
}

fn first_inbox_id(){
    let rows = inbox()
    if rows.len() == 0 { return "" }
    rows[0].id
}

fn depth_name(){
    if depth == 0 { "L0 - compact glance" } else { if depth == 1 { "L1 - expanded card" } else { "L2 - full app view" } }
}

fn set_depth(d){
    depth = d
    ui.glance.set_visible(d == 0)
    ui.expanded.set_visible(d == 1)
    ui.full.set_visible(d == 2)
    sync()
}

fn sync(){
    let rows = inbox()
    ui.glance_body.render()
    ui.expanded_body.render()
    ui.full_body.render()
    ui.count.set_text("" + rows.len() + " in Inbox - demo")
    ui.depth_now.set_text("Showing: " + depth_name())
    ui.undo_bar.set_visible(last_undo != "")
    ui.undo.set_text("Undo " + last_undo_label)
    if depth == 0 { ui.d0.set_text("L0 *") } else { ui.d0.set_text("L0") }
    if depth == 1 { ui.d1.set_text("L1 *") } else { ui.d1.set_text("L1") }
    if depth == 2 { ui.d2.set_text("L2 *") } else { ui.d2.set_text("L2") }
}

fn archive(id){
    let m = msg_of(id)
    if m == nil { return }
    if has_item(archived, id) { return }
    archived.push(id)
    last_id = id
    last_undo = "archive"
    last_undo_label = "Archive"
    status = "Archived (demo) - use Undo in the bottom bar."
    if sel == id { sel = first_inbox_id() }
    sync()
}

fn undo_archive(id){
    archived.retain(|x| x != id)
    last_undo = ""
    last_undo_label = ""
    status = "Restored to Inbox (demo)."
    sync()
}

fn undo_send(id){
    sent.retain(|s| s.id != id)
    last_undo = ""
    last_undo_label = ""
    status = "Send (demo) undone - the demo message was removed."
    sync()
}

fn undo(){
    if last_undo == "archive" { undo_archive(last_id) }
    if last_undo == "send" { undo_send(last_id) }
}

fn toggle_read(id){
    for m in msgs { if m.id == id { m.unread = !m.unread } }
    status = "Toggled read state (demo)."
    sync()
}

fn restore_all(){
    archived.clear()
    last_undo = ""
    last_undo_label = ""
    status = "Restored all demo messages."
    if sel == "" { sel = first_inbox_id() }
    sync()
}

fn send_demo(){
    let body = draft.trim()
    if body == "" { status = "Nothing to send - write something first."; return }
    let id = "s" + "" + (sent.len() + 1)
    sent.push({id: id to: "Ana Ruiz" subject: "Re: Contract renewal" preview: body at: "now"})
    last_id = id
    last_undo = "send"
    last_undo_label = "Send (demo)"
    draft = ""
    status = "Sent (demo) - nothing left this device."
    sync()
}

