source lead  sys.dataset(id: "m1", fields: [title, subtitle, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value])
source inbox sys.dataset(id: "m1", fields: [title, subtitle, as_of, status])

state mode  { shape: enum[brief, open, reply, sent], initial: .brief }
state draft { shape: text, initial: "" }
state read  { shape: bool, initial: true }
state archived { shape: bool, initial: false }

# `toggle` is for booleans; an enum is only ever set from an enum token
# (framework-l0 §3). open_msg is the card's own detail expansion, not a route
# into the native bundle.
event open_msg  { mode: set(.open) }
event reply     { mode: set(.reply) }
event cancel    { mode: set(.brief) }
event send      { mode: set(.sent) }
event back      { mode: set(.brief) }
event toggle_read { read: toggle }
event archive   { archived: set(true) }
