# ledger calendar.glance@0.1.0
# level:   L0
# profile: ui/l0
# model:   dev.studio.cards.calendar
#
# CALENDAR family's L0 glance: the next event, expandable to its own detail.
# L0/L1/L2 are PRESENTATION depths, not parser levels — this file is language L0
# at every depth. Native previews live in card-templates/calendar/bundle/main.splash.
#
# Fixture: glance.data.json — synthetic demo events. No account, no calendar
# service, nothing synced, so the card SAYS DEMO.
#
# Every event has card-local behaviour. `when` branches reference NAMED views
# (as in mail-request.card) rather than deep literal nesting, and `when` has no
# `else`. RSVP is card-local and reversible: a second tap of the same answer
# clears it, so no state is a dead end.
#
# Shape follows the shipped calendar-event.card: dataset record, two Tiles,
# Icon(.calendar) row, and declared lifecycle copy.

source next_ev sys.dataset(id: "e1", fields: [title, subtitle, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value])
source agenda   sys.dataset(id: "e1", fields: [title, subtitle, as_of, status])

state mode { shape: enum[glance, detail], initial: .glance }
state rsvp { shape: enum[unanswered, going, maybe, declined], initial: .unanswered }

event open_detail { mode: set(.detail) }
event back        { mode: set(.glance) }
event rsvp_going  { rsvp: set(.going) }
event rsvp_maybe  { rsvp: set(.maybe) }
event rsvp_no     { rsvp: set(.declined) }
event rsvp_clear  { rsvp: set(.unanswered) }

copy app      { class: vocabulary, en: "Calendar", zh: "日历" }
copy eyebrow  { class: vocabulary, en: "CALENDAR · GLANCE · DEMO", zh: "日历 · 概览 · 演示" }
copy open     { class: vocabulary, en: "Open",        zh: "打开" }
copy back     { class: vocabulary, en: "‹ Back",      zh: "‹ 返回" }
copy going    { class: vocabulary, en: "Going",       zh: "参加" }
copy maybe    { class: vocabulary, en: "Maybe",       zh: "或许" }
copy no       { class: vocabulary, en: "No",          zh: "不去" }
copy clear    { class: vocabulary, en: "Clear answer", zh: "清除回答" }
copy h_rsvp   { class: vocabulary, en: "YOUR REPLY · STAYS LOCAL", zh: "你的回复 · 仅存本地" }
copy h_none   { class: vocabulary, en: "No answer yet", zh: "尚未回答" }
copy h_going  { class: vocabulary, en: "Answer: Going", zh: "回答：参加" }
copy h_maybe  { class: vocabulary, en: "Answer: Maybe", zh: "回答：或许" }
copy h_decl   { class: vocabulary, en: "Answer: No",   zh: "回答：不去" }
copy demo_note { class: vocabulary, en: "Demo data. No calendar account, nothing is synced.", zh: "演示数据。无日历账号，不会同步。" }

# Lifecycle strings are declared copy, never inline (framework-l0 §1).
copy loading { class: vocabulary, en: "Loading demo events…", zh: "正在加载演示事件…" }
copy offline { class: vocabulary, en: "Can't load demo events", zh: "无法加载演示事件" }

view root Surface(pad: .tight) {
  Col(gap: 10) {
    Row(gap: 8, align: .center) {
      Icon(name: .calendar, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(value: next_ev.as_of)
    }
    TextEyebrow(text: copy.eyebrow)
    when next_ev.$state == .pending { pending }
    when next_ev.$state == .failed  { offline_row }
    when next_ev.$state == .ready   {
      when mode == .glance { glance_row }
      when mode == .detail { detail }
    }
    when agenda.$state == .ready {
      Rule
      Row(gap: 8, align: .center) {
        TextCaption(text: agenda.subtitle, width: .fill)
        TextCaption(value: agenda.as_of)
      }
    }
  }
}

view pending Col(gap: 8) {
  TextBody(text: copy.loading, width: .fill)
}

view offline_row Col(gap: 8) {
  TextBody(text: copy.offline, width: .fill)
}

view glance_row Col(gap: 10) {
  TextTitle(text: next_ev.title, width: .fill)
  TextRow(text: next_ev.subtitle, width: .fill)
  Rule
  Row(gap: 8) {
    Tile(label: next_ev.metric1_label, value: next_ev.metric1_value)
    Tile(label: next_ev.metric2_label, value: next_ev.metric2_value)
  }
  Row(gap: 8) {
    Chip(text: copy.open, on_tap: open_detail, tone: .primary)
  }
  TextCaption(text: copy.demo_note, width: .fill)
}

view detail Col(gap: 10) {
  TextTitle(text: next_ev.title, width: .fill)
  Row(gap: 8, align: .center) {
    Icon(name: .location, size: .row)
    TextRow(text: next_ev.subtitle, width: .fill)
  }
  Row(gap: 8) {
    Tile(label: next_ev.metric1_label, value: next_ev.metric1_value)
    Tile(label: next_ev.metric2_label, value: next_ev.metric2_value)
  }
  TextBody(text: next_ev.summary, width: .fill)
  TextEyebrow(text: copy.h_rsvp)
  when rsvp == .unanswered {
    Row(gap: 8) {
      Chip(text: copy.going, on_tap: rsvp_going, tone: .primary)
      Chip(text: copy.maybe, on_tap: rsvp_maybe)
      Chip(text: copy.no, on_tap: rsvp_no)
    }
  }
  when rsvp == .going  { Row(gap: 8, align: .center) { TextRow(text: copy.h_going, width: .fill) Chip(text: copy.clear, on_tap: rsvp_clear) } }
  when rsvp == .maybe  { Row(gap: 8, align: .center) { TextRow(text: copy.h_maybe, width: .fill) Chip(text: copy.clear, on_tap: rsvp_clear) } }
  when rsvp == .declined { Row(gap: 8, align: .center) { TextRow(text: copy.h_decl, width: .fill) Chip(text: copy.clear, on_tap: rsvp_clear) } }
  Row(gap: 8) {
    Chip(text: copy.back, on_tap: back)
  }
}

# ledger mail.glance@0.1.0
# level:   L0
# profile: ui/l0
# model:   dev.studio.cards.mail
#
# MAIL family's L0 glance: the reusable declarative half of the Mail template.
# L0/L1/L2 are PRESENTATION depths, not parser levels — this file is language L0
# at every depth. Native previews live in card-templates/mail/bundle/main.splash.
#
# Fixture: glance.data.json — synthetic demo records. No mailbox is read, no
# account is used, nothing is sent, so the card SAYS DEMO.
#
# OFFLINE SOURCE CONTRACT (why these declarations look unusual):
#   * Fixture values are looked up by SOURCE ALIAS, so the fixture keys are
#     `lead` and `inbox` — not `m1`/`rest`.
#   * `id:` is deliberately OMITTED. With an explicit id the fields lower to
#     live sys.dataset(id, field) calls, which the offline checked VM cannot
#     serve; omitting it lets the fixture values lower to plain literals.
#   * Every read of a lifecycle-bound field sits inside a `.$state == .ready`
#     guard, so nothing outside a guard can lower to a live call.
#
# `when` takes no else, and branches reference named views (mail-request.card).

source lead  sys.dataset(fields: [title, subtitle, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value])
source inbox sys.dataset(fields: [title, subtitle, as_of, status])

state mode  { shape: enum[brief, open, reply, sent], initial: .brief }
state draft { shape: text, initial: "" }
state read  { shape: enum[unread, read], initial: .unread }
state kept  { shape: enum[kept, gone], initial: .kept }

event open_msg     { mode: set(.open) }
event reply        { mode: set(.reply) }
event cancel       { mode: set(.brief) }
event back         { mode: set(.brief) }
event send         { mode: set(.sent) }
event mark_read    { read: set(.read) }
event mark_unread  { read: set(.unread) }
event archive      { kept: set(.gone) }
event undo_archive { kept: set(.kept) }
event edit         { draft: set($value) }

copy app       { class: vocabulary, en: "Mail",         zh: "邮件" }
copy eyebrow   { class: vocabulary, en: "MAIL · GLANCE · DEMO", zh: "邮件 · 概览 · 演示" }
copy open      { class: vocabulary, en: "Open",         zh: "打开" }
copy back      { class: vocabulary, en: "‹ Back",       zh: "‹ 返回" }
copy reply     { class: vocabulary, en: "Reply",        zh: "回复" }
copy send      { class: vocabulary, en: "Send (demo)",  zh: "发送（演示）" }
copy cancel    { class: vocabulary, en: "Cancel",       zh: "取消" }
copy mark_r    { class: vocabulary, en: "Mark as read", zh: "标为已读" }
copy mark_u    { class: vocabulary, en: "Mark as unread", zh: "标为未读" }
copy archived  { class: vocabulary, en: "Archive (demo)", zh: "归档（演示）" }
copy undo      { class: vocabulary, en: "Undo",         zh: "撤销" }
copy h_draft   { class: vocabulary, en: "REPLY · DRAFT STAYS LOCAL", zh: "回复 · 草稿仅存本地" }
copy demo_note { class: vocabulary, en: "Demo data. No mailbox, no account, no send.", zh: "演示数据。无邮箱、无账号、不会发送。" }

# Lifecycle strings are declared copy, never inline (framework-l0 §1).
copy loading { class: vocabulary, en: "Loading demo messages…", zh: "正在加载演示邮件…" }
copy offline { class: vocabulary, en: "Can't load demo messages", zh: "无法加载演示邮件" }
copy sent    { class: vocabulary, en: "Queued (demo) — nothing left this device", zh: "已入队（演示）— 未离开本机" }

view root Surface(pad: .tight) {
  Col(gap: 10) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
    }
    when lead.$state == .pending { loading_row }
    when lead.$state == .failed  { offline_row }
    when lead.$state == .ready   {
      Row(gap: 8, align: .center) {
        TextCaption(text: copy.eyebrow, width: .fill)
        TextCaption(value: lead.as_of)
      }
      when mode == .brief { brief }
      when mode == .open  { detail }
      when mode == .reply { compose }
      when mode == .sent  { sent_row }
    }
    when inbox.$state == .ready {
      Rule
      Row(gap: 8, align: .center) {
        TextCaption(text: inbox.subtitle, width: .fill)
        TextCaption(value: inbox.as_of)
      }
    }
  }
}

view loading_row Col(gap: 8) {
  TextBody(text: copy.loading, width: .fill)
