# ledger news.glance@0.1.0
# level:   L0
# profile: ui/l0
# model:   dev.studio.cards.news
#
# NEWS family's L0 glance: the lead story, expandable to its own detail with a
# reversible Save. L0/L1/L2 are PRESENTATION depths, not parser levels — this
# file is language L0 at every depth.
#
# Fixture: glance.data.json — synthetic demo stories. No feed is fetched and no
# article page is opened, so `summary` is a demo summary written with the record
# and the card says so.
#
# OFFLINE SOURCE CONTRACT:
#   * fixture keys are the SOURCE ALIASES (lead, rest)
#   * `id:` is omitted so fixture values lower to literals, not live calls
#   * every lifecycle-bound read sits inside a `.$state == .ready` guard
#   * `when` has no else and branches reference named views
#
# Kept deliberately compact: two sources, two state fields, one detail view.

source lead sys.dataset(fields: [title, subtitle, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value])
source rest sys.dataset(fields: [title, subtitle, as_of, status])

state mode { shape: enum[brief, open], initial: .brief }
state kept { shape: enum[dropped, saved], initial: .dropped }

event open_story { mode: set(.open) }
event back       { mode: set(.brief) }
event save       { kept: set(.saved) }
event remove     { kept: set(.dropped) }

copy app      { class: vocabulary, en: "News",         zh: "新闻" }
copy eyebrow  { class: vocabulary, en: "NEWS · GLANCE · DEMO", zh: "新闻 · 概览 · 演示" }
copy open     { class: vocabulary, en: "Open",         zh: "打开" }
copy back     { class: vocabulary, en: "‹ Back",       zh: "‹ 返回" }
copy save     { class: vocabulary, en: "Save",         zh: "收藏" }
copy remove   { class: vocabulary, en: "Remove",       zh: "取消收藏" }
copy note     { class: vocabulary, en: "Demo summary. No feed is fetched and no article page is opened.", zh: "演示摘要。未抓取信息源，也不会打开文章页面。" }
copy loading  { class: vocabulary, en: "Loading demo stories…", zh: "正在加载演示新闻…" }
copy offline  { class: vocabulary, en: "Can't load demo stories", zh: "无法加载演示新闻" }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    when lead.$state == .pending { TextBody(text: copy.loading, width: .fill) }
    when lead.$state == .failed  { TextBody(text: copy.offline, width: .fill) }
    when lead.$state == .ready   {
      Row(gap: 8, align: .center) {
        Icon(name: .bell, size: .row)
        TextCaption(text: copy.eyebrow, width: .fill)
        TextCaption(value: lead.as_of)
      }
      when mode == .brief { brief }
      when mode == .open  { detail }
    }
    when rest.$state == .ready {
      TextCaption(text: rest.subtitle, width: .fill)
      TextCaption(value: rest.as_of)
    }
  }
}

view brief Col(gap: 8) {
  TextTitle(text: lead.title, width: .fill)
  TextRow(text: lead.subtitle, width: .fill)
  TextBody(text: lead.summary, width: .fill)
  Rule
  Row(gap: 8) {
    Tile(label: lead.metric1_label, value: lead.metric1_value)
    Tile(label: lead.metric2_label, value: lead.metric2_value)
  }
  Row(gap: 8) {
    Chip(text: copy.open, on_tap: open_story, tone: .primary)
  }
  TextCaption(text: copy.note, width: .fill)
}

view detail Col(gap: 8) {
  TextTitle(text: lead.title, width: .fill)
  Row(gap: 8, align: .center) {
    TextRow(text: lead.subtitle, width: .fill)
    TextCaption(value: lead.as_of)
  }
  TextBody(text: lead.summary, width: .fill)
  Rule
  Row(gap: 8) {
    when kept == .dropped { Chip(text: copy.save, on_tap: save, tone: .primary) }
    when kept == .saved   { Chip(text: copy.remove, on_tap: remove) }
    Chip(text: copy.back, on_tap: back)
  }
  TextCaption(text: copy.note, width: .fill)
}

