let accent = #x007aff
let line = #xe5e5ea
let demo_bg = #xfff3cd
let demo_ink = #x8a0b00

let saved = []
let status = "Demo feed."
let depth = 0
let sel = "n1"
let route = "list"
let filter = "all"

// ---------- state helpers ----------

fn pick(cond, on, off){ if cond { on } else { off } }

fn st_of(id){
    for s in stories { if s.id == id { return s } }
    nil
}

fn is_saved(id){
    for s in saved { if s == id { return true } }
    false
}

fn n_saved(){ saved.len() }

fn lead(){
    for s in stories { return s }
    nil
}

fn say(s){ status = s; ui.status.set_text(s) }

fn depth_name(){
    if depth == 0 { return "L0 Glance" }
    if depth == 1 { return "L1 Story" }
    if route == "detail" { return "L2 Story" }
    return "L2 Feed"
}

fn set_depth(d){
    depth = d
    route = "list"
    say("")
    sync()
}

fn do_open(id){
    sel = id
    route = "detail"
    set_depth(2)
    route = "detail"
    sync()
}

fn do_back(){
    route = "list"
    say("")
    sync()
}

fn do_save(id){
    if is_saved(id) { return }
    saved.push(id)
    let s = st_of(id)
    if s == nil { return }
    say("Saved " + s.outlet)
    sync()
}

fn do_remove(id){
    if !is_saved(id) { return }
    saved.retain(|x| x != id)
    say("Removed from Saved")
    sync()
}

fn set_filter(f){
    filter = f
    say("")
    sync()
}

// ---------- chrome sync ----------

fn sync(){
    ui.glance.set_visible(depth == 0)
    ui.expanded.set_visible(depth == 1)
    ui.full.set_visible(depth == 2)

    ui.count.set_text("" + stories.len() + " stories · " + "" + n_saved() + " saved")
