# ledger photo.glance@0.1.0
# level:   L0
# profile: ui/l0
# model:   dev.studio.cards.photo
#
# PHOTO family's L0 glance: one photo record, expandable to its own detail.
# L0/L1/L2 are PRESENTATION depths, not parser levels — this file is language L0
# at every depth. Native previews live in card-templates/photo/bundle/main.splash.
#
# Fixture: glance.data.json — synthetic demo records. This offline build loads no
# image assets and reads no photo library, so the card STATES the picture is not
# shown here rather than implying a photo is on screen.
#
# OFFLINE SOURCE CONTRACT:
#   * fixture keys are the SOURCE ALIASES (lead, more);
#   * `id:` is OMITTED so fixture values lower to literals;
#   * every lifecycle-bound read sits inside a `.$state == .ready` guard;
#   * `when` takes no else, and branches reference named views.

source lead sys.dataset(fields: [title, subtitle, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value])
source more sys.dataset(fields: [title, subtitle, as_of, status])

state mode { shape: enum[glance, detail], initial: .glance }
state fav  { shape: enum[plain, favorite], initial: .plain }

event open_detail { mode: set(.detail) }
event back        { mode: set(.glance) }
event favorite    { fav: set(.favorite) }
event unfavorite  { fav: set(.plain) }

copy app      { class: vocabulary, en: "Photo", zh: "照片" }
copy nomedia  { class: vocabulary, en: "PHOTO NOT SHOWN IN THIS BUILD", zh: "此版本不显示照片" }
copy open     { class: vocabulary, en: "Open", zh: "打开" }
copy back     { class: vocabulary, en: "‹ Back", zh: "‹ 返回" }
copy favorite { class: vocabulary, en: "Favorite", zh: "收藏" }
copy unfav    { class: vocabulary, en: "Remove from Favorites", zh: "取消收藏" }
copy demo_note { class: vocabulary, en: "Demo album. No photo library is read here.", zh: "演示相册。此版本不读取照片库。" }

# Lifecycle strings are declared copy, never inline (framework-l0 §1).
copy loading { class: vocabulary, en: "Loading demo album…", zh: "正在加载演示相册…" }
copy offline { class: vocabulary, en: "Can't load demo album", zh: "无法加载演示相册" }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .photo, size: .row)
      TextCaption(text: copy.app, width: .fill)
    }
    when lead.$state == .pending { loading_row }
    when lead.$state == .failed  { offline_row }
    when lead.$state == .ready   {
      TextCaption(text: copy.nomedia, width: .fill)
      when mode == .glance { glance_row }
      when mode == .detail { detail }
    }
    when more.$state == .ready {
      Rule
      Row(gap: 8, align: .center) {
        TextCaption(text: more.subtitle, width: .fill)
        TextCaption(value: more.as_of)
      }
    }
  }
}

view loading_row Col {
  TextBody(text: copy.loading, width: .fill)
}

view offline_row Col {
  TextBody(text: copy.offline, width: .fill)
}

view glance_row Col(gap: 8) {
  TextTitle(text: lead.title, width: .fill)
  TextRow(text: lead.subtitle, width: .fill)
  Row(gap: 8) {
    Chip(text: copy.open, on_tap: open_detail, tone: .primary)
  }
  TextCaption(text: copy.demo_note, width: .fill)
}

view detail Col(gap: 8) {
  TextTitle(text: lead.title, width: .fill)
  Row(gap: 8, align: .center) {
    Icon(name: .location, size: .row)
    TextRow(text: lead.subtitle, width: .fill)
  }
  Row(gap: 8) {
    Tile(label: lead.metric1_label, value: lead.metric1_value)
    Tile(label: lead.metric2_label, value: lead.metric2_value)
  }
  TextBody(text: lead.summary, width: .fill)
  Row(gap: 8) {
    when fav == .plain    { Chip(text: copy.favorite, on_tap: favorite, tone: .primary) }
    when fav == .favorite { Chip(text: copy.unfav, on_tap: unfavorite) }
  }
  Row(gap: 8) {
    Chip(text: copy.back, on_tap: back)
  }
}

// Video card template — dev.studio.cards.youtube
// All records are SYNTHETIC DEMO DATA in this app's local list. This offline
// Studio loads no thumbnails and opens no player url, so nothing is previewed
// or played here: each row states that plainly and no control pretends to play.
//
// Depths are PRESENTATION depths (UI), not parser levels:
//   L0  lead video at a glance
//   L1  expanded record with a reversible Watch later
//   L2  list (All / Watch later) -> record detail

let vids = [
    {id: "v1" title: "Slow harbour morning, timelapse" channel: "Riverside Field Notes"
        length: "08:24" ago: "2 days ago" views: "41.2K"
        note: "A demo record written to exercise this card. Nothing is streamed or played here."}
    {id: "v2" title: "Restoring a harbour crane, part 2" channel: "Docklands Workshop"
        length: "21:07" ago: "5 days ago" views: "128K"
        note: "A demo record written to exercise this card. No player is opened from this build."}
    {id: "v3" title: "Weeknight cycling: four rivers route" channel: "Alex Outdoors"
        length: "14:51" ago: "1 week ago" views: "17.9K"
        note: "A demo record written to exercise this card. Video is not loaded offline."}
]

let ground = #xf2f2f7
let surface = #xffffff
let ink = #x1c1c1e
let ink2 = #x3c3c43
let muted = #x8e8e93
let accent = #x007aff
let line = #xe5e5ea
let demo_bg = #xfff3cd
let demo_ink = #x8a0b00

let later = []
let status = "Demo queue."
let depth = 0
let sel = "v1"
let route = "list"
let tab = "all"

// ---------- state helpers ----------

fn pick(cond, on, off){ if cond { on } else { off } }

fn vd_of(id){
    for v in vids { if v.id == id { return v } }
    nil
}

fn is_later(id){
    for l in later { if l == id { return true } }
    false
}

fn n_later(){ later.len() }

fn lead(){
    for v in vids { return v }
    nil
}

// L0 always shows the first record, so its action must target that record
// rather than whatever a previous route left selected.
fn lead_id(){
    let m = lead()
    if m == nil { return "" }
    m.id
}

fn say(s){ status = s; ui.status.set_text(s) }

fn depth_name(){
    if depth == 0 { return "L0 Glance" }
    if depth == 1 { return "L1 Video" }
    if route == "detail" { return "L2 Video" }
    return "L2 List"
}

fn set_depth(d){
    depth = d
    route = "list"
    say("Showing " + depth_name())
    sync()
}

fn do_open(id){
    sel = id
    route = "detail"
    set_depth(2)
    route = "detail"
    say("Showing " + depth_name())
    sync()
}

fn do_back(){
    route = "list"
    say("Showing " + depth_name())
    sync()
}

fn do_later(id){
    if is_later(id) { return }
    later.push(id)
    let v = vd_of(id)
    if v == nil { return }
    say("Added to Watch later")
    sync()
}

fn do_drop(id){
    if !is_later(id) { return }
    later.retain(|x| x != id)
    let v = vd_of(id)
    if v == nil { return }
    say("Removed from Watch later")
    sync()
}

// The dynamically labelled button must do what its label currently says, so one
// action serves both directions and is reversible wherever it appears.
fn do_toggle_later(id){
    if is_later(id) { do_drop(id) } else { do_later(id) }
}

fn set_tab(t){
    tab = t
    say("Showing " + pick(t == "all", "All videos", "Watch later"))
    sync()
}

// ---------- chrome sync ----------

fn sync(){
    ui.glance.set_visible(depth == 0)
    ui.expanded.set_visible(depth == 1)
    ui.full.set_visible(depth == 2)

    ui.count.set_text("" + vids.len() + " videos · " + "" + n_later() + " in Watch later")
    ui.status.set_text(status)
    ui.depth_now.set_text(depth_name())

    let m = lead()
    ui.g_title.set_text(m.title)
    ui.g_channel.set_text(m.channel)
    ui.g_len.set_text(m.length)
    ui.g_ago.set_text(m.ago)

    let s = vd_of(sel)
    ui.x_title.set_text(s.title)
    ui.x_channel.set_text(s.channel)
    ui.x_meta.set_text(s.length + " · " + s.ago + " · " + s.views + " views")
    ui.x_note.set_text(s.note)
    ui.x_action.set_text(pick(is_later(s.id), "Remove from Watch later", "Watch later"))

    ui.rd_title.set_text(s.title)
    ui.rd_channel.set_text(s.channel)
    ui.rd_meta.set_text(s.length + " · " + s.ago + " · " + s.views + " views")
    ui.rd_note.set_text(s.note)
    ui.rd_action.set_text(pick(is_later(s.id), "Remove from Watch later", "Watch later"))

    ui.l2_list.set_visible(route == "list")
    ui.l2_detail.set_visible(route == "detail")

    ui.r1.set_visible(tab == "all")
    ui.r2.set_visible(tab == "all")
    ui.r3.set_visible(tab == "all")
    ui.r1_l.set_visible(tab == "later" && is_later("v1"))
    ui.r2_l.set_visible(tab == "later" && is_later("v2"))
    ui.r3_l.set_visible(tab == "later" && is_later("v3"))
    ui.later_empty.set_visible(tab == "later" && n_later() == 0)

    ui.r1_b.set_text(pick(is_later("v1"), "Remove", "Watch later"))
    ui.r2_b.set_text(pick(is_later("v2"), "Remove", "Watch later"))
    ui.r3_b.set_text(pick(is_later("v3"), "Remove", "Watch later"))
    ui.r1_lb.set_text(pick(is_later("v1"), "Remove", "Watch later"))
    ui.r2_lb.set_text(pick(is_later("v2"), "Remove", "Watch later"))
    ui.r3_lb.set_text(pick(is_later("v3"), "Remove", "Watch later"))

    ui.tab_all.set_text(pick(tab == "all", "● All", "All"))
    ui.tab_later.set_text(pick(tab == "later", "● Watch later", "Watch later"))
}

