        padding: Inset{left: 16 right: 16 top: 6 bottom: 8}
        SolidView{width: Fill height: 1 draw_bg.color: line}
        RoundedView{width: Fill height: Fit flow: Right spacing: 4
            padding: Inset{left: 4 right: 4 top: 4 bottom: 4}
            draw_bg.color: #xe5e5ea draw_bg.border_radius: 12.0
            b0 := Seg{text: "L0" on_click: || set_depth(0)}
            b1 := Seg{text: "L1" on_click: || set_depth(1)}
            b2 := Seg{text: "L2" on_click: || set_depth(2)}
        }
        View{width: Fill height: Fit flow: Right align: Align{y: 0.5} spacing: 8
            depth_now := Label{text: "" draw_text.color: ink draw_text.text_style: theme.font_bold{font_size: 12}}
            status := Label{text: "" draw_text.color: muted draw_text.text_style.font_size: 12}
        }
    }
}

fn boot(){
    say("Showing L0 Glance")
    sync()
}

start_timeout(0.05, || boot())

# ledger youtube.glance@0.1.0
# level:   L0
# profile: ui/l0
# model:   dev.studio.cards.youtube
#
# VIDEO family's L0 glance: one video record, expandable to its own detail.
# L0/L1/L2 are PRESENTATION depths, not parser levels — this file is language L0
# at every depth. Native previews live in card-templates/youtube/bundle/main.splash.
#
# Fixture: glance.data.json — synthetic demo records. This offline build runs no
# search, loads no thumbnail and opens no player url, so the card STATES that
# playback is unavailable here instead of implying a video is on screen.
#
# OFFLINE SOURCE CONTRACT:
#   * fixture keys are the SOURCE ALIASES (lead, more);
#   * `id:` is OMITTED so fixture values lower to literals;
#   * every lifecycle-bound read sits inside a `.$state == .ready` guard;
#   * `when` takes no else, and branches reference named views.
#
# The shipped youtube.card searches a live source and hands a player url to
# sys.link. Neither is possible offline, so this card uses a plain sys.dataset
# record and makes no playback claim.

source lead sys.dataset(fields: [title, subtitle, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value])
source more sys.dataset(fields: [title, subtitle, as_of, status])

state mode  { shape: enum[glance, detail], initial: .glance }
state later { shape: enum[none, saved], initial: .none }

event open_detail { mode: set(.detail) }
event back        { mode: set(.glance) }
event add_later   { later: set(.saved) }
event drop_later  { later: set(.none) }

copy app      { class: vocabulary, en: "Videos", zh: "视频" }
copy noplay   { class: vocabulary, en: "PLAYBACK UNAVAILABLE IN THIS BUILD", zh: "此版本无法播放" }
copy open     { class: vocabulary, en: "Open", zh: "打开" }
copy back     { class: vocabulary, en: "‹ Back", zh: "‹ 返回" }
copy later    { class: vocabulary, en: "Watch later", zh: "稍后观看" }
copy drop     { class: vocabulary, en: "Remove from Watch later", zh: "从稍后观看中移除" }
copy demo_note { class: vocabulary, en: "Demo list. No search or playback here.", zh: "演示列表。此版本不搜索，也不播放。" }

# Lifecycle strings are declared copy, never inline (framework-l0 §1).
copy loading { class: vocabulary, en: "Loading demo videos…", zh: "正在加载演示视频…" }
copy offline { class: vocabulary, en: "Can't load demo videos", zh: "无法加载演示视频" }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .video, size: .row)
      TextCaption(text: copy.app, width: .fill)
    }
    when lead.$state == .pending { loading_row }
    when lead.$state == .failed  { offline_row }
    when lead.$state == .ready   {
      TextCaption(text: copy.noplay, width: .fill)
      when mode == .glance { glance_row }
      when mode == .detail { detail }
    }
    when more.$state == .ready {
      Rule
      Row(gap: 8, align: .center) {
        TextCaption(text: more.subtitle, width: .fill)
        TextCaption(value: more.as_of)
      }
    }
  }
}

view loading_row Col {
  TextBody(text: copy.loading, width: .fill)
}

view offline_row Col {
  TextBody(text: copy.offline, width: .fill)
}

view glance_row Col(gap: 8) {
  TextTitle(text: lead.title, width: .fill)
  TextRow(text: lead.subtitle, width: .fill)
  Row(gap: 8) {
    Chip(text: copy.open, on_tap: open_detail, tone: .primary)
  }
  TextCaption(text: copy.demo_note, width: .fill)
}

view detail Col(gap: 8) {
  TextTitle(text: lead.title, width: .fill)
  TextRow(text: lead.subtitle, width: .fill)
  Row(gap: 8) {
    Tile(label: lead.metric1_label, value: lead.metric1_value)
    Tile(label: lead.metric2_label, value: lead.metric2_value)
  }
  TextBody(text: lead.summary, width: .fill)
  Row(gap: 8) {
    when later == .none  { Chip(text: copy.later, on_tap: add_later, tone: .primary) }
    when later == .saved { Chip(text: copy.drop, on_tap: drop_later) }
  }
  Row(gap: 8) {
    Chip(text: copy.back, on_tap: back)
  }
}

